<script setup>
import { computed, ref, watch, onBeforeUnmount } from 'vue'
import { useRoute, onBeforeRouteLeave } from 'vue-router'
import { Heart, ArrowRight, ShieldCheck, Check, X, RotateCcw, AlertCircle, Coffee, ChevronDown, Sparkles } from 'lucide-vue-next'
import BrandLogo from '../components/BrandLogo.vue'
import { api } from '../api'
import { money, initials } from '../utils/format'
import { useAppStore } from '../stores/app'
const route=useRoute(),store=useAppStore(),data=ref(null),loading=ref(true),state=ref('form'),error=ref(''),code=ref(''),amount=ref(300),scenario=ref('success'),paid=ref(null),showDemo=ref(true),cancelling=ref(false)
let controller, loadVersion=0
const amountValid=computed(()=>Number.isInteger(Number(amount.value))&&Number(amount.value)>=10&&Number(amount.value)<=50000)
const presets=computed(()=>data.value?.qr.type==='receipt'?[5,10,15].map(percent=>({value:Math.max(10,Math.round(data.value.qr.bill*percent/100)),label:`${percent}%`})):[{value:150,label:'150 ₽'},{value:300,label:'300 ₽'},{value:500,label:'500 ₽'}])
async function load(){const version=++loadVersion;loading.value=true;error.value='';code.value='';state.value='form';data.value=null;try{const result=await api.resolveQr(route.params.id);if(version!==loadVersion)return;data.value=result;amount.value=presets.value[1].value}catch(e){if(version===loadVersion){error.value=e.message;code.value=e.code;state.value='invalid'}}finally{if(version===loadVersion)loading.value=false}}
watch(()=>route.params.id,()=>{controller?.abort();scenario.value='success';load()},{immediate:true})
function scenarioChange(){if(scenario.value==='invalid'){state.value='invalid';error.value='Этот QR-код не найден или больше не действует.';code.value='INVALID_QR'}else if(scenario.value==='repeated'){state.value='invalid';error.value='По этому одноразовому QR-коду уже оставили чаевые.';code.value='USED_QR'}else if(data.value){state.value='form';error.value=''}else{load()}}
async function pay(){if(!amountValid.value||state.value==='processing')return;state.value='processing';cancelling.value=false;error.value='';controller=new AbortController();try{const result=await api.pay({qrId:route.params.id,amount:Number(amount.value),scenario:scenario.value,signal:controller.signal});paid.value=result;state.value=result.status;if(store.session)store.load().catch(()=>{})}catch(e){error.value=e.message;code.value=e.code;state.value=['INVALID_QR','USED_QR'].includes(e.code)?'invalid':'error'}}
function cancel(){cancelling.value=true;controller?.abort()}
function retry(){state.value='form';error.value=''}
onBeforeRouteLeave(()=>state.value==='processing'?false:true)
onBeforeUnmount(()=>controller?.abort())
</script>
<template><main class="pay-page"><header class="pay-header"><BrandLogo/><span><ShieldCheck :size="15"/>Демонстрационная оплата</span></header><div class="pay-layout"><div class="pay-intro"><span class="eyebrow">БЛАГОДАРНОСТЬ В ОДНО КАСАНИЕ</span><h1>За заботу.<br>За улыбку.<br><em>За хороший день.</em></h1><p>Маленькое «спасибо» тому,<br>кто сделал ваш визит особенным.</p><div class="pay-flower">✳</div><span class="pay-intro-note">Никаких наличных. Только благодарность.</span></div><div class="pay-right"><section class="pay-card" aria-live="polite"><div v-if="loading" class="empty"><span class="spinner"></span><h3>Готовим ваше «спасибо»…</h3></div><template v-else-if="state==='form'&&data"><div class="pay-restaurant"><span class="restaurant-symbol"><Coffee :size="19"/></span>{{ data.merchant.name }}<span class="tag">ресторан</span></div><div class="pay-person"><span class="avatar pay-avatar" :class="data.employee.color">{{ initials(data.employee.name) }}<span class="avatar-heart"><Heart :size="15" fill="currentColor"/></span></span><h2>{{ data.employee.name }}</h2><p>{{ data.employee.role }} · был рядом с вами сегодня</p></div><h3 class="pay-choose">Сколько «спасибо» оставим?</h3><p v-if="data.qr.type==='receipt'" class="muted small-text">{{ data.qr.label }} · сумма {{ money(data.qr.bill) }}</p><div class="tip-options"><button v-for="p in presets" :key="p.value" @click="amount=p.value" :class="{selected:Number(amount)===p.value}">{{ p.label }}<span v-if="data.qr.type==='receipt'">{{ money(p.value) }}</span><Heart v-else :size="15"/></button></div><label class="custom-amount">Или своя сумма<div><input v-model="amount" type="number" min="10" max="50000" step="1" inputmode="numeric" aria-label="Своя сумма чаевых"><span>₽</span></div></label><p v-if="!amountValid" class="error-text">Введите целую сумму от 10 до 50 000 ₽.</p><div class="pay-total"><span>Ваши чаевые</span><strong>{{ money(Number(amount)||0) }}</strong></div><button class="btn btn-primary pay-submit" :disabled="!amountValid" @click="pay">Оплатить чаевые<ArrowRight :size="19"/></button><p class="pay-safe"><ShieldCheck :size="14"/>Демо: деньги не списываются</p><button class="text-link pay-cancel" @click="state='cancelled'">Отменить</button></template><div v-else-if="state==='processing'" class="pay-result"><div class="result-icon processing"><span class="spinner"></span></div><h2>Передаём ваше спасибо</h2><p>Обрабатываем демоплатёж {{ money(amount) }}.<br>Это займёт пару секунд.</p><button class="btn btn-outline full" @click="cancel" :disabled="cancelling">{{ cancelling?'Отменяем…':'Отменить оплату' }}</button></div><div v-else-if="state==='success'" class="pay-result"><div class="result-icon success"><Check :size="38"/></div><span class="eyebrow">БЛАГОДАРНОСТЬ ДОСТАВЛЕНА</span><h2>Вы сделали чей-то<br>день лучше!</h2><p>{{ data?.employee.name }} получил(а) ваше<br>«спасибо» — {{ money(paid?.amount) }}.</p><div class="payment-receipt"><span>Демоплатёж</span><strong>{{ money(paid?.amount) }}</strong><span>Статус</span><span class="status success">Успешно</span></div><p class="muted small-text">Деньги не списывались. Платёж уже в истории ресторана.</p><button v-if="data?.qr.type==='personal'" class="btn btn-primary full" @click="retry">Оставить ещё чаевые<Heart :size="17"/></button><button v-else class="btn btn-outline full" @click="load">Проверить одноразовый QR</button><RouterLink v-if="store.session" to="/app/payments" class="text-link pay-cancel">Открыть историю платежей<ArrowRight :size="15"/></RouterLink></div><div v-else-if="['declined','error','cancelled','invalid'].includes(state)" class="pay-result"><div class="result-icon" :class="state==='cancelled'?'neutral':'warning'"><X v-if="state==='cancelled'" :size="34"/><AlertCircle v-else :size="34"/></div><h2>{{ state==='cancelled'?'Оплата отменена':state==='declined'?'Не получилось оплатить':state==='invalid'?(code==='USED_QR'?'Спасибо уже сказано':'QR-код недействителен'):'Что-то пошло не так' }}</h2><p>{{ state==='cancelled'?'Вы отменили оплату. Деньги не списывались.':state==='declined'?'Демобанк отклонил платёж. Попробуйте ещё раз с другим сценарием.':error }}</p><p v-if="state==='invalid'" class="muted small-text">{{ code==='USED_QR'?'Одноразовый QR можно оплатить только один раз.':'Попросите сотрудника показать новый QR-код.' }}</p><button v-if="state!=='invalid'&&data" class="btn btn-primary full" @click="retry"><RotateCcw :size="17"/>Попробовать снова</button><button v-else-if="data" class="btn btn-outline full" @click="scenario='success';load()">Вернуться к исходному QR</button><RouterLink v-else to="/" class="btn btn-outline full">На главную</RouterLink></div></section><section v-if="showDemo" class="demo-controls"><div><Sparkles :size="16"/><strong>Пульт демонстрации</strong><span>без реальных списаний</span></div><label>Сценарий оплаты<select v-model="scenario" @change="scenarioChange" :disabled="state==='processing'"><option value="success">Успешная оплата</option><option value="declined">Отказ банка</option><option value="invalid">Недействительный QR</option><option value="repeated">Повторная оплата одноразового QR</option><option value="cancelled">Отмена платежа</option></select></label><p>Исходы симулируются. Отказ и отмена при обработке сохраняются в истории. Повторный платёж также блокируется после реальной успешной демооплаты одноразового QR.</p></section></div></div><footer class="pay-footer">Работает на <strong>tipro.</strong><span>Создано для благодарности</span></footer></main></template>
